fn frame(t: i32) {
    host::display::clear(0x0e1013);
    if host::display::state_get(4) == 0 {
        host::display::state_set(4, 1);
        host::display::state_set(2, 20);
        host::display::state_set(3, 10);
    }
    let tab: i32 = host::display::state_get(1);
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    let mut click: i32 = 0;
    if down == 1 && prev == 0 {
        click = 1;
    }
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();

    let mut ca: i32 = 0x1a1e26;
    let mut cb: i32 = 0x1a1e26;
    if tab == 0 {
        ca = 0x2c3442;
    } else {
        cb = 0x2c3442;
    }
    host::display::fill_rect(40, 40, 200, 50, ca);
    host::display::draw_string(76, 56, "C TO F", 0xffffff, 2);
    host::display::fill_rect(272, 40, 200, 50, cb);
    host::display::draw_string(296, 56, "KM TO MI", 0xffffff, 2);

    let mut val: i32 = host::display::state_get(2 + tab);
    host::display::fill_rect(60, 160, 70, 60, 0x232833);
    host::display::draw_char(84, 178, 45, 0xffffff, 3);
    host::display::fill_rect(382, 160, 70, 60, 0x232833);
    host::display::draw_char(406, 178, 43, 0xffffff, 3);
    host::display::draw_number(210, 172, val, 0xffffff, 5);

    if click == 1 {
        if py >= 40 && py < 90 {
            if px >= 40 && px < 240 {
                host::display::state_set(1, 0);
            } else if px >= 272 && px < 472 {
                host::display::state_set(1, 1);
            }
        }
        if py >= 160 && py < 220 {
            if px >= 60 && px < 130 && val > 0 {
                val = val - 1;
                host::display::state_set(2 + tab, val);
            }
            if px >= 382 && px < 452 && val < 999 {
                val = val + 1;
                host::display::state_set(2 + tab, val);
            }
        }
    }

    host::display::fill_rect(40, 280, 432, 2, 0x2a3038);
    if tab == 0 {
        host::display::draw_string(60, 310, "CELSIUS", 0x556677, 1);
        host::display::draw_string(60, 360, "FAHRENHEIT", 0x8899aa, 1);
        host::display::draw_number(210, 340, val * 9 / 5 + 32, 0x66ddff, 6);
    } else {
        host::display::draw_string(60, 310, "KILOMETERS", 0x556677, 1);
        host::display::draw_string(60, 360, "MILES X 1000", 0x8899aa, 1);
        host::display::draw_number(210, 340, val * 621, 0x66ddff, 6);
    }
    host::display::present();
}
